with flagged as (select *, case when paid_at - lag(paid_at) over (partition by status order by paid_at asc, id asc) > interval '60' day then 1 else 0 end as new_group_flag from payments) select id, order_id, method, amount, paid_at, status, sum(new_group_flag) over (partition by status order by paid_at asc, id asc rows between unbounded preceding and current row) as session_id from flagged
